-- English local authorities (county councils, unitaries, districts, metropolitan districts, London boroughs).
-- Generated by data/build_authorities.mjs on 2026-09-26. Do not edit by hand.
-- Codes: ONS WD26_LAD26_CTYUA26_RGN26_CTRY26_UK_LU (fetched 2026-09-26). Council names + websites: GOV.UK Local Links Manager (fallback: ONS area name).
-- Counts: E10=21, E06=63, E07=164, E08=36, E09=33; total 317.
-- Counties (E10) are inserted first so parent_gss references resolve.

on conflict (gss_code) do update set
  name = excluded.name,
  type = excluded.type,
  parent_gss = excluded.parent_gss,
  website = coalesce(excluded.website, authorities.website);
